svg.script:
firebase.initializeApp({
  apiKey: 'AIzaSyBFQFc5KcUDWT7r-V0UvyUznQ6IeCESINg',
  authDomain: 'larp-larp-sahur.firebaseapp.com',
  databaseURL: 'https://larp-larp-sahur-default-rtdb.firebaseio.com',
  projectId: 'larp-larp-sahur',
  storageBucket: 'larp-larp-sahur.firebasestorage.app',
  messagingSenderId: '810674651244',
  appId: '1:810674651244:web:85fdecc13a4dc8dd0a5849'
});
const db = firebase.database();

let uid = null;
const authReady = firebase.auth().signInAnonymously().then(cred => { uid = cred.user.uid; });
authReady.catch(() => {});

function store(key, value) {
  try {
    if (value === undefined) return localStorage.getItem(key);
    localStorage.setItem(key, value);
  } catch (e) { return null; }
}
let username = '';

const messagesEl = document.getElementById('messages');
const input = document.getElementById('msg-input');
const sendBtn = document.getElementById('send-btn');
const listEl = document.getElementById('user-list');
const countEl = document.getElementById('count');
const statusEl = document.getElementById('status');

const messagesRef = db.ref('channels/hive/messages');

function addMessage(m) {
  const mine = m.uid === uid;
  const wrap = document.createElement('div');
  wrap.className = 'msg' + (mine ? ' me' : '');
  if (!mine) {
    const who = document.createElement('div');
    who.className = 'who';
    who.textContent = m.username || 'Guest';
    wrap.appendChild(who);
  }
  const bubble = document.createElement('div');
  bubble.className = 'bubble';
  bubble.textContent = m.text || '';
  wrap.appendChild(bubble);
  const nearBottom = messagesEl.scrollHeight - messagesEl.scrollTop - messagesEl.clientHeight < 80;
  messagesEl.appendChild(wrap);
  if (nearBottom || mine) messagesEl.scrollTop = messagesEl.scrollHeight;
}

function dbError(err) {
  const code = (err && (err.code || err.message)) || 'unknown';
  statusEl.textContent =
    /api-key/i.test(code) ? 'Add your Firebase apiKey in the initializeApp config.' :
    /operation-not-allowed|admin-restricted/i.test(code) ? 'Turn on Anonymous sign-in in Firebase console > Authentication > Sign-in method.' :
    /permission/i.test(code) ? 'Firebase blocked this (permission denied). Check you are signed in and the path matches your rules.' :
    'Firebase error: ' + code;
  console.error('Firebase error:', err);
}

function startMessages() {
  messagesRef.orderByChild('timestamp').limitToLast(100).on('child_added', snap => addMessage(snap.val()), dbError);
}

function send() {
  const text = input.value.trim();
  if (!text || !uid) return;
  messagesRef.push({
    uid: uid,
    username: username,
    text: text,
    timestamp: firebase.database.ServerValue.TIMESTAMP
  }).catch(dbError);
  input.value = '';
  resize();
}

const SITE = 'the-hive';   
const onlineRef = db.ref('presence');
let myConnRef = null;   

function startPresence() {
myConnRef = db.ref('presence/' + uid);
let connected = false;

function goOnline() {
  if (!connected || document.hidden || !username || !myConnRef) return;
  myConnRef.onDisconnect().remove()
    .then(() => myConnRef.set({ site: SITE, username: username, since: firebase.database.ServerValue.TIMESTAMP }))
    .catch(dbError);
}
function goOffline() {
  if (myConnRef) myConnRef.remove().catch(() => {});
}

db.ref('.info/connected').on('value', snap => {
  connected = snap.val() === true;
  if (connected) {
    if (/^(Connecting|Reconnecting|Can.t reach)/.test(statusEl.textContent)) statusEl.textContent = '';
    goOnline();
  } else {
    statusEl.textContent = 'Reconnecting…';
  }
});

document.addEventListener('visibilitychange', () => {
  if (document.hidden) goOffline(); else goOnline();
});
window.addEventListener('pagehide', goOffline);

setTimeout(() => {
  if (!connected) statusEl.textContent = "Can't reach Firebase. Open this file from localhost or your own hosting, not inside Claude's preview.";
}, 8000);

onlineRef.on('value', snap => {
  const seen = {};
  snap.forEach(child => {
    const u = child.val();
    if (u && u.site === SITE) seen[child.key] = u.username || 'Guest';
  });
  const names = Object.keys(seen).map(id => ({ id: id, name: seen[id] }));
  listEl.textContent = '';
  names.forEach(u => {
    const li = document.createElement('li');
    const av = document.createElement('span');
    av.className = 'avatar';
    av.textContent = u.name.charAt(0).toUpperCase();
    const dot = document.createElement('span');
    dot.className = 'dot';
    av.appendChild(dot);
    const nm = document.createElement('span');
    nm.className = 'name';
    nm.textContent = u.id === uid ? u.name + ' (you)' : u.name;
    li.appendChild(av);
    li.appendChild(nm);
    listEl.appendChild(li);
  });
  countEl.textContent = names.length;
}, dbError);
}

const gate = document.getElementById('gate');
const appEl = document.getElementById('app');
const nameInput = document.getElementById('name-input');
const joinBtn = document.getElementById('join-btn');

function join() {
  const n = nameInput.value.trim().slice(0, 20);
  if (!n) return;
  username = n;
  gate.hidden = true;
  appEl.hidden = false;
  document.getElementById('title').hidden = false;
  authReady.then(() => { startMessages(); startPresence(); }).catch(dbError);
  input.focus();
}
nameInput.addEventListener('input', () => { joinBtn.disabled = !nameInput.value.trim(); });
joinBtn.addEventListener('click', join);
nameInput.addEventListener('keydown', e => {
  if (e.key === 'Enter') { e.preventDefault(); join(); }
});

function resize() {
  input.style.height = 'auto';
  input.style.height = Math.min(input.scrollHeight, 160) + 'px';
  sendBtn.disabled = !input.value.trim();
}
input.addEventListener('input', resize);
sendBtn.addEventListener('click', send);
input.addEventListener('keydown', e => {
  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); }
});
